create or replace function public.zoom_service_login_lookup(requested_username text) returns table(user_id uuid, username text, initials text, role text, status text, must_change_password boolean, internal_email text, failed_attempts integer, failure_window_started_at timestamptz, locked_until timestamptz) language sql security definer set search_path=public,private,pg_catalog as $$ select p.id,p.username::text,p.initials,p.role,p.status,p.must_change_password,i.internal_email::text,s.failed_attempts,s.failure_window_started_at,s.locked_until from public.zoom_profiles p join private.zoom_auth_identities i on i.user_id=p.id join private.zoom_login_security s on s.user_id=p.id where p.username=lower(trim(requested_username)); $$;
create or replace function public.zoom_service_set_login_security(account uuid, failures integer, window_started timestamptz, locked timestamptz, session uuid) returns void language sql security definer set search_path=public,private,pg_catalog as $$ update private.zoom_login_security set failed_attempts=failures,failure_window_started_at=window_started,locked_until=locked,current_session_id=session,updated_at=now() where user_id=account; $$;
revoke all on function public.zoom_service_login_lookup(text), public.zoom_service_set_login_security(uuid,integer,timestamptz,timestamptz,uuid) from public;
grant execute on function public.zoom_service_login_lookup(text), public.zoom_service_set_login_security(uuid,integer,timestamptz,timestamptz,uuid) to service_role;
